{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Do you hold US stock?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Vocom is build-to-order with no US warehouse. Standard lead time is 6 to 8 weeks, expedited air freight is 2 to 3 weeks, and high-count or custom builds take up to 10 weeks."
      }
    },
    {
      "@type": "Question",
      "name": "Can you be a second source for specs my supplier is slow on?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Rollable ribbon, high-count, micro and indoor plenum cable are the specs most often quoted in months elsewhere. Send the spec and we return a price and a delivery date."
      }
    },
    {
      "@type": "Question",
      "name": "What should I send to get a quote?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fiber count, fiber type, construction, jacket rating (OFNP, OFNR or LSZH), footage, needed-by date and destination. Any spec can be built to order as a custom build."
      }
    },
    {
      "@type": "Question",
      "name": "Can orders be split across ship dates?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Large orders are commonly split into tranches so cable arrives against your customers' build phases instead of sitting in your yard."
      }
    },
    {
      "@type": "Question",
      "name": "Where can I find catalog information?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The Resources page has our fiber optic cable catalog with counts, specs and how to order. For anything outside it, send the spec and we will quote it."
      }
    }
  ]
}

